'use strict';
(function(){const T=JourneyTraits;
const mechanics={
tree:['Round 3: marked roots damage and immobilize allies. Round 4: channels healing through living sprouts; killing them limits the heal. Round 5: replenishes sprouts.','Rodada 3: raízes marcadas causam dano e imobilizam. Rodada 4: canaliza cura pelos brotos vivos; eliminá-los reduz a cura. Rodada 5: repõe brotos.'],
colossus:['From round 2, golems protect the boss: defeat them to break armor and expose it. Round 3 adds a warned ground impact. From round 4, the exposed boss attacks faster and harder.','Da rodada 2 em diante, golems protegem o chefe: elimine-os para romper a armadura e expô-lo. Rodada 3 adiciona impacto sinalizado. A partir da rodada 4, exposto, ataca mais rápido e mais forte.'],
slime:['From round 2, the boss detaches mass as slimes. Total health includes this mass: kill slimes before they return. Round 3 adds repeated splits. From round 4, destroyed mass leaves damaging, slowing puddles.','Da rodada 2 em diante, o chefe desprende massa em slimes. A vida total inclui essa massa: elimine-os antes de voltarem ao chefe. Rodada 3 adiciona divisões repetidas. Da rodada 4 em diante, massa destruída deixa poças de dano e lentidão.'],
dragon:['Round 3: a warned fire cone. From round 4, it leaves burning ground. Round 5: faster breaths and reinforcement wyverns.','Rodada 3: cone de fogo sinalizado. Da rodada 4 em diante, deixa chão em chamas. Rodada 5: sopros mais frequentes e reforços de wyverns.'],
hydra:['Round 3: marked acid impacts; living basilisks increase the number of marks. From round 4, impacts leave acid pools.','Rodada 3: impactos de ácido marcados; basiliscos vivos aumentam a quantidade de marcas. Da rodada 4 em diante, impactos deixam poças ácidas.'],
kraken:['Round 3: marked tentacle impacts immobilize allies. Living spawns add another mark. From round 4, impacted allies are pulled toward the Kraken.','Rodada 3: impactos marcados de tentáculos imobilizam. Crias vivas adicionam outra marca. Da rodada 4 em diante, aliados atingidos são puxados ao Kraken.'],
lich:['From round 3, channels resurrection of fallen skeletons with limited charges. Takes extra damage while channeling. From round 4, resurrection causes an impact around the corpse.','Da rodada 3 em diante, canaliza ressurreição de esqueletos caídos com cargas limitadas. Recebe dano adicional ao canalizar. Da rodada 4 em diante, a ressurreição causa impacto ao redor do corpo.'],
naga:['Serpent-men apply stacking venom with basic attacks. Round 3: a warned gaze cone damages and immobilizes. From round 4, the gaze also applies venom.','Homens-serpente aplicam veneno cumulativo com ataques básicos. Rodada 3: cone de olhar sinalizado causa dano e imobiliza. Da rodada 4 em diante, o olhar também aplica veneno.'],
manticore:['Round 3: three warned lines of spikes. From round 4, wounded targets are marked for the cubs to hunt; cubs move faster while marks last.','Rodada 3: três linhas de espinhos sinalizadas. Da rodada 4 em diante, alvos atingidos são marcados para a caça dos filhotes; filhotes se movem mais rápido enquanto há marcas.']};
function info(unit,raid=false){if(!unit||!G.BY[unit.type])return;const t=G.BY[unit.type],r=S.raid,leader=raid&&unit.type===(r.bossType||JourneyRaid.TREE),cfg=r?.config;let st=unit.stats;
if(raid)st={hp:leader?r.hp:cfg.sproutHp,maxhp:leader?r.maxHp:cfg.sproutHp,atk:leader?cfg.bossAtk:cfg.sproutAtk,defense:leader?cfg.bossDefense:cfg.sproutDefense,rate:leader?cfg.bossRate:cfg.sproutRate,speed:leader?0:cfg.sproutSpeed,range:leader?cfg.bossRange:t.range};
if(raid&&!leader&&S.bossEncounter?.form===2)st={hp:unit.type==='boss_seal'?700:550,maxhp:unit.type==='boss_seal'?700:550,atk:t.atk,defense:t.defense,rate:t.rate,speed:t.speed,range:t.range};
if(!st)st=G.stats(unit,S,JourneyEncounterMemory.previous(S)?.units||[],true);
const d=Object.entries(JourneyBosses.D).find(([id])=>unit.type==='boss_'+id||unit.type==='boss_'+id+'_2')?.[1],description=d?L(d.descEn,d.descPt):raid?L(...(mechanics[r.kind||'tree']||[t.detail||'Enemy reinforcement.',t.detail||'Reforço inimigo.'])):skillDescription(t),ability=d?L(d.skillEn,d.skillPt):raid?L('Raid mechanics','Mecânicas da raid'):I18n.t(t.ability);
journeyPanel(t.name,'<div class="eyebrow">'+(raid?(leader?'RAID · BOSS':L('RAID · MINION','RAID · LACAIO')):L('Previous formation · upgrade ','Formação anterior · upgrade ')+(unit.level||0)+(unit.fused?' · '+L('Fused','Fundido'):''))+'</div><img class="p3-enemy-art" src="'+(CA[unit.type]?.art||CA[unit.type]?.sprite)+'" alt="'+esc(t.name)+'"><div class="p3-enemy-stats">'+[['♥',L('Health','Vida'),Math.ceil(st.hp)+(raid&&leader?' / '+Math.ceil(st.maxhp):'')],['⚔',L('Attack','Ataque'),Math.round(st.atk)],['◇',L('Defense','Defesa'),Math.round(st.defense)],['↻',L('Attacks/s','Ataques/s'),(1/st.rate).toFixed(2)],['➟',L('Movement','Movimento'),Math.round(st.speed)],['◎',L('Range','Alcance'),Math.round(st.range)]].map(([icon,label,value])=>'<div><b>'+icon+' '+value+'</b><small>'+label+'</small></div>').join('')+'</div>'+(raid?'<p>'+L('Boss health persists between rounds. Defeat it before losing five rounds. Minions enter from round 2.','A vida do chefe persiste entre rodadas. Derrote-o antes de perder cinco rodadas. Lacaios entram da rodada 2 em diante.')+'</p>':'<p class="panel-hint">'+L(unit.stats?'Stats recorded at the start of the previous round.':'Enemy unit stats.',unit.stats?'Atributos registrados no início da rodada anterior.':'Atributos da unidade inimiga.')+'</p>')+'<h3>'+esc(ability)+'</h3><p>'+esc(description)+'</p>'+(!raid?'<div class="p3-enemy-traits">'+t.traits.map(tr=>'<details><summary>'+Icon(traitIcon(tr))+' '+esc(T.D[tr]?L(T.D[tr].en,T.D[tr].pt):tr)+'</summary><p>'+esc(L(T.D[tr]?.desc||'',T.D[tr]?.descPT||''))+'</p></details>').join('')+'</div>':'<p>'+L('Round ','Rodada ')+S.round+' · '+L('Remaining losses: ','Derrotas restantes: ')+Math.max(0,(cfg.maxLosses||5)-(S.score?.[1]||0))+'</p>'),metaButton('close',L('Back','Voltar'),'','primary'));}
const prepare=prep;prep=function(){prepare();const previous=JourneyEncounterMemory.previous(S);document.querySelector('.hidden-enemy.previous-enemy')?.remove();for(const el of document.querySelectorAll('[data-enemy-index]')){const u=previous?.units[+el.dataset.enemyIndex];if(u){el.setAttribute('aria-label',L('Hold to inspect ','Segure para inspecionar ')+G.BY[u.type].name);el.title=el.getAttribute('aria-label');}}const formation=S?.raid?JourneyRaid.formation(S):null;for(const [i,el]of [...document.querySelectorAll('.raid-preview img')].entries()){const u=formation?.[i]||(S.bossEncounter?{type:'boss_'+S.bossEncounter.id}:null);if(!u)continue;el.dataset.enemyType=u.type;el.setAttribute('role','button');el.tabIndex=0;el.setAttribute('aria-label',L('Hold to inspect ','Segure para inspecionar ')+G.BY[u.type].name);}};
let hold=null,suppressed=0;function inspect(el){if(S?.phase!=='prep')return;info(el.dataset.enemyType?{type:el.dataset.enemyType,level:0}:JourneyEncounterMemory.previous(S)?.units[+el.dataset.enemyIndex],!!S.raid);}function cancel(){if(hold)clearTimeout(hold.timer);hold=null;}
window.addEventListener('pointerdown',e=>{const el=e.target.closest?.('[data-enemy-index],[data-enemy-type]');if(!el||S?.phase!=='prep'||document.querySelector('#overlay')||e.button!==0)return;cancel();hold={el,x:e.clientX,y:e.clientY,id:e.pointerId,timer:setTimeout(()=>{suppressed=performance.now()+900;inspect(el);cancel();},450)};},true);
window.addEventListener('pointermove',e=>{if(hold&&e.pointerId===hold.id&&Math.hypot(e.clientX-hold.x,e.clientY-hold.y)>10)cancel();},true);for(const event of ['pointerup','pointercancel','blur'])window.addEventListener(event,cancel,true);
window.addEventListener('contextmenu',e=>{if(e.target.closest?.('[data-enemy-index],[data-enemy-type]'))e.preventDefault();},true);
window.addEventListener('click',e=>{const el=e.target.closest?.('[data-enemy-index],[data-enemy-type]');if(el){e.preventDefault();e.stopImmediatePropagation();if(performance.now()>=suppressed&&e.detail===0)inspect(el);}},true);
window.addEventListener('keydown',e=>{const el=e.target.closest?.('[data-enemy-index],[data-enemy-type]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();inspect(el);}},true);
})();
